// server/src/db/tags.ts
function rowToAPI2(row) {
  return { _id: row.id, name: row.name, color: row.color };
}
async function getTags(db2, userId) {
  const rows = db2.prepare("SELECT * FROM tags WHERE user_id = ? ORDER BY name").all(userId);
  return rows.map(rowToAPI2);
}
async function createTag(db2, userId, data) {
  const id = generateId();
  const wanted = data.name.trim().toLocaleLowerCase("tr");
  const existing = db2.prepare("SELECT name FROM tags WHERE user_id = ?").all(userId);
  if (existing.some((t) => t.name.trim().toLocaleLowerCase("tr") === wanted)) {
    throw new Error("A tag with this name already exists");
  }
  try {
    db2.prepare("INSERT INTO tags (id, user_id, name, color) VALUES (?, ?, ?, ?)").run(id, userId, data.name, data.color);
  } catch (err) {
    if (String(err.message).includes("UNIQUE")) {
      throw new Error("A tag with this name already exists");
    }
    throw new Error(err.message);
  }
  const tag2 = db2.prepare("SELECT * FROM tags WHERE id = ? AND user_id = ?").get(id, userId);
  return rowToAPI2(tag2);
}
async function updateTag(db2, userId, data) {
  const columns = [];
  const values = [];
  if (data.name) {
    columns.push("name = ?");
    values.push(data.name);
  }
  if (data.color) {
    columns.push("color = ?");
    values.push(data.color);
  }
  if (columns.length > 0) {
    let result;
    try {
      result = db2.prepare(`UPDATE tags SET ${columns.join(", ")} WHERE id = ? AND user_id = ?`).run(...values, data._id, userId);
    } catch (err) {
      if (String(err.message).includes("UNIQUE")) throw new Error("A tag with this name already exists");
      throw err;
    }
    if (result.changes === 0) throw new Error("Tag not found");
  }
  const tag2 = db2.prepare("SELECT * FROM tags WHERE id = ? AND user_id = ?").get(data._id, userId);
  if (!tag2) throw new Error("Tag not found");
  return rowToAPI2(tag2);
}
async function deleteTag(db2, userId, tagId) {
  db2.prepare("DELETE FROM tags WHERE id = ? AND user_id = ?").run(tagId, userId);
}

