// server/src/db/premarket.ts
function eventRowToAPI(row) {
  return {
    _id: row.id,
    eventName: row.event_name,
    eventTime: row.event_time,
    eventDate: row.event_date,
    releaseId: row.release_id
  };
}
function itemRowToAPI(row) {
  return {
    _id: row.id,
    label: row.label,
    sortOrder: row.sort_order,
    createdAt: row.created_at
  };
}
function completionRowToAPI(row) {
  return {
    _id: row.id,
    itemId: row.item_id,
    completedDate: row.completed_date,
    completedAt: row.completed_at
  };
}
function maskWebhookUrl(url2) {
  if (!url2) return null;
  if (url2.length <= 6) return "\u2022\u2022\u2022\u2022\u2022\u2022";
  return "\u2022\u2022\u2022\u2022\u2022\u2022" + url2.slice(-6);
}
function settingsRowToAPI(row) {
  return {
    _id: row.id,
    resetTime: row.reset_time,
    timezone: row.timezone,
    hasDiscordWebhook: !!row.discord_webhook_url,
    discordWebhookMasked: maskWebhookUrl(row.discord_webhook_url)
  };
}
async function getChecklistItems(db2, userId) {
  const rows = db2.prepare(
    "SELECT * FROM premarket_checklist_items WHERE user_id = ? ORDER BY sort_order ASC"
  ).all(userId);
  return rows.map(itemRowToAPI);
}
async function createChecklistItem(db2, userId, item) {
  const id = generateId();
  db2.prepare(
    `INSERT INTO premarket_checklist_items (id, user_id, label, sort_order, created_at)
     VALUES (?, ?, ?, ?, ?)`
  ).run(id, userId, item.label, item.sortOrder, (/* @__PURE__ */ new Date()).toISOString());
  const row = db2.prepare("SELECT * FROM premarket_checklist_items WHERE id = ? AND user_id = ?").get(id, userId);
  return itemRowToAPI(row);
}
async function updateChecklistItem(db2, userId, itemId, updates) {
  const columns = [];
  const values = [];
  if (updates.label !== void 0) {
    columns.push("label = ?");
    values.push(updates.label);
  }
  if (updates.sortOrder !== void 0) {
    columns.push("sort_order = ?");
    values.push(updates.sortOrder);
  }
  if (columns.length > 0) {
    const result = db2.prepare(
      `UPDATE premarket_checklist_items SET ${columns.join(", ")}
         WHERE id = ? AND user_id = ?`
    ).run(...values, itemId, userId);
    if (result.changes === 0) throw new Error("Checklist item not found");
  }
  const row = db2.prepare("SELECT * FROM premarket_checklist_items WHERE id = ? AND user_id = ?").get(itemId, userId);
  if (!row) throw new Error("Checklist item not found");
  return itemRowToAPI(row);
}
async function deleteChecklistItem(db2, userId, itemId) {
  db2.prepare("DELETE FROM premarket_checklist_items WHERE id = ? AND user_id = ?").run(itemId, userId);
}
async function reorderChecklistItems(db2, userId, orderedIds) {
  const update = db2.prepare(
    "UPDATE premarket_checklist_items SET sort_order = ? WHERE id = ? AND user_id = ?"
  );
  const run = db2.transaction(() => {
    for (let i = 0; i < orderedIds.length; i++) {
      update.run(i, orderedIds[i], userId);
    }
  });
  run();
}
async function getCompletions(db2, userId, date5) {
  const rows = db2.prepare(
    "SELECT * FROM premarket_checklist_completions WHERE user_id = ? AND completed_date = ?"
  ).all(userId, date5);
  return rows.map(completionRowToAPI);
}
async function getCompletionsByDate(db2, userId, startDate, endDate) {
  const rows = db2.prepare(
    `SELECT item_id, completed_date FROM premarket_checklist_completions
       WHERE user_id = ? AND completed_date >= ? AND completed_date <= ?`
  ).all(userId, startDate, endDate);
  const out = {};
  for (const r3 of rows) {
    (out[r3.completed_date] ||= []).push(r3.item_id);
  }
  return out;
}
async function toggleCompletion(db2, userId, itemId, date5) {
  const existing = db2.prepare(
    `SELECT id FROM premarket_checklist_completions
       WHERE user_id = ? AND item_id = ? AND completed_date = ?`
  ).get(userId, itemId, date5);
  if (existing) {
    db2.prepare("DELETE FROM premarket_checklist_completions WHERE id = ?").run(existing.id);
    return { completed: false };
  }
  db2.prepare(
    `INSERT INTO premarket_checklist_completions (id, user_id, item_id, completed_date, completed_at)
     VALUES (?, ?, ?, ?, ?)`
  ).run(generateId(), userId, itemId, date5, (/* @__PURE__ */ new Date()).toISOString());
  return { completed: true };
}
async function getSettings(db2, userId) {
  const row = db2.prepare("SELECT * FROM premarket_settings WHERE user_id = ?").get(userId);
  return row ? settingsRowToAPI(row) : null;
}
async function upsertSettings(db2, userId, settings) {
  db2.prepare(
    `INSERT INTO premarket_settings (id, user_id, reset_time, timezone)
     VALUES (?, ?, ?, ?)
     ON CONFLICT(user_id) DO UPDATE SET
       reset_time = excluded.reset_time,
       timezone = excluded.timezone`
  ).run(generateId(), userId, settings.resetTime, settings.timezone);
  const row = db2.prepare("SELECT * FROM premarket_settings WHERE user_id = ?").get(userId);
  return settingsRowToAPI(row);
}
async function saveDiscordWebhook(db2, userId, encryptedUrl) {
  db2.prepare(
    `INSERT INTO premarket_settings (id, user_id, discord_webhook_url)
     VALUES (?, ?, ?)
     ON CONFLICT(user_id) DO UPDATE SET
       discord_webhook_url = excluded.discord_webhook_url`
  ).run(generateId(), userId, encryptedUrl);
  const row = db2.prepare("SELECT * FROM premarket_settings WHERE user_id = ?").get(userId);
  return settingsRowToAPI(row);
}
async function getEconomicEvents(db2, date5) {
  const rows = db2.prepare(
    `SELECT * FROM premarket_economic_events
       WHERE event_date = ?
       ORDER BY event_time IS NULL, event_time ASC`
  ).all(date5);
  return rows.map(eventRowToAPI);
}

