// server/src/db/backtesting.ts
function sessionRowToAPI(row) {
  return {
    _id: row.id,
    name: row.name ?? null,
    ticker: row.ticker,
    startDate: row.start_date,
    endDate: row.end_date ?? null,
    isActive: !!row.is_active,
    createdAt: row.created_at
  };
}
function tradeRowToAPI(row) {
  return {
    _id: row.id,
    sessionId: row.session_id,
    result: row.result,
    profitFactor: row.profit_factor,
    timeOfDay: row.time_of_day,
    createdAt: row.created_at
  };
}
async function getSessions(db2, userId) {
  const rows = db2.prepare("SELECT * FROM backtesting_sessions WHERE user_id = ? ORDER BY created_at DESC").all(userId);
  return rows.map(sessionRowToAPI);
}
async function getSessionsWithStats(db2, userId) {
  const sessions = await getSessions(db2, userId);
  if (sessions.length === 0) return [];
  const trades = db2.prepare("SELECT session_id, result, profit_factor FROM backtesting_trades WHERE user_id = ?").all(userId);
  const statsBySession = {};
  for (const t of trades) {
    if (!statsBySession[t.session_id]) {
      statsBySession[t.session_id] = { wins: 0, losses: 0, pfSum: 0 };
    }
    if (t.result === "win") statsBySession[t.session_id].wins++;
    else statsBySession[t.session_id].losses++;
    statsBySession[t.session_id].pfSum += t.profit_factor;
  }
  return sessions.map((s) => {
    const st = statsBySession[s._id];
    if (!st) return { ...s, tradeCount: 0, winCount: 0, lossCount: 0, winRate: 0, avgProfitFactor: 0 };
    const total = st.wins + st.losses;
    return {
      ...s,
      tradeCount: total,
      winCount: st.wins,
      lossCount: st.losses,
      winRate: total > 0 ? st.wins / total * 100 : 0,
      avgProfitFactor: total > 0 ? st.pfSum / total : 0
    };
  });
}
async function createSession(db2, userId, session) {
  const id = generateId();
  const run = db2.transaction(() => {
    db2.prepare("UPDATE backtesting_sessions SET is_active = 0 WHERE user_id = ? AND is_active = 1").run(userId);
    db2.prepare(
      `INSERT INTO backtesting_sessions (id, user_id, name, ticker, start_date, is_active, created_at)
       VALUES (?, ?, ?, ?, ?, 1, ?)`
    ).run(
      id,
      userId,
      session.name || null,
      session.ticker.toUpperCase(),
      session.startDate,
      (/* @__PURE__ */ new Date()).toISOString()
    );
  });
  run();
  const row = db2.prepare("SELECT * FROM backtesting_sessions WHERE id = ? AND user_id = ?").get(id, userId);
  return sessionRowToAPI(row);
}
async function endSession(db2, userId, sessionId, endDate) {
  const result = db2.prepare(
    "UPDATE backtesting_sessions SET is_active = 0, end_date = ? WHERE id = ? AND user_id = ?"
  ).run(endDate, sessionId, userId);
  if (result.changes === 0) throw new Error("Session not found");
  const row = db2.prepare("SELECT * FROM backtesting_sessions WHERE id = ? AND user_id = ?").get(sessionId, userId);
  return sessionRowToAPI(row);
}
async function continueSession(db2, userId, sessionId) {
  const run = db2.transaction(() => {
    db2.prepare("UPDATE backtesting_sessions SET is_active = 0 WHERE user_id = ? AND is_active = 1").run(userId);
    const result = db2.prepare(
      "UPDATE backtesting_sessions SET is_active = 1, end_date = NULL WHERE id = ? AND user_id = ?"
    ).run(sessionId, userId);
    if (result.changes === 0) throw new Error("Session not found");
  });
  run();
  const row = db2.prepare("SELECT * FROM backtesting_sessions WHERE id = ? AND user_id = ?").get(sessionId, userId);
  return sessionRowToAPI(row);
}
async function deleteSession(db2, userId, sessionId) {
  db2.prepare("DELETE FROM backtesting_sessions WHERE id = ? AND user_id = ?").run(sessionId, userId);
}
async function getTrades2(db2, userId) {
  const rows = db2.prepare(
    `SELECT * FROM backtesting_trades
       WHERE user_id = ?
       ORDER BY created_at ASC`
  ).all(userId);
  return rows.map(tradeRowToAPI);
}
async function getTradesForSession(db2, userId, sessionId) {
  const rows = db2.prepare(
    `SELECT * FROM backtesting_trades
       WHERE user_id = ? AND session_id = ?
       ORDER BY created_at ASC`
  ).all(userId, sessionId);
  return rows.map(tradeRowToAPI);
}
async function addTrade(db2, userId, trade2) {
  const id = generateId();
  db2.prepare(
    `INSERT INTO backtesting_trades (id, session_id, user_id, result, profit_factor, time_of_day, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).run(
    id,
    trade2.sessionId,
    userId,
    trade2.result,
    trade2.profitFactor,
    trade2.timeOfDay,
    (/* @__PURE__ */ new Date()).toISOString()
  );
  const row = db2.prepare("SELECT * FROM backtesting_trades WHERE id = ? AND user_id = ?").get(id, userId);
  return tradeRowToAPI(row);
}
async function deleteTrade2(db2, userId, tradeId) {
  db2.prepare("DELETE FROM backtesting_trades WHERE id = ? AND user_id = ?").run(tradeId, userId);
}

