async function findByBrokerConnectionId4(db2, brokerConnectionId) {
  const row = db2.prepare("SELECT * FROM webull_connections WHERE broker_connection_id = ?").get(brokerConnectionId);
  return row || null;
}
async function create4(db2, brokerConnectionId, oauthNonce) {
  const id = generateId();
  try {
    db2.prepare(
      `INSERT INTO webull_connections (id, broker_connection_id, oauth_nonce, created_at)
       VALUES (?, ?, ?, ?)`
    ).run(id, brokerConnectionId, oauthNonce, (/* @__PURE__ */ new Date()).toISOString());
  } catch (err) {
    throw new Error(`Failed to create webull connection: ${err.message}`);
  }
  const row = db2.prepare("SELECT * FROM webull_connections WHERE id = ?").get(id);
  return row;
}
async function updateByBrokerConnectionId4(db2, brokerConnectionId, updates) {
  const allowed = [
    "access_token",
    "refresh_token",
    "token_expires_at",
    "oauth_nonce",
    "account_id"
  ];
  const columns = [];
  const values = [];
  for (const key2 of allowed) {
    if (updates[key2] !== void 0) {
      columns.push(`${key2} = ?`);
      values.push(updates[key2]);
    }
  }
  if (columns.length === 0) return;
  try {
    db2.prepare(
      `UPDATE webull_connections SET ${columns.join(", ")} WHERE broker_connection_id = ?`
    ).run(...values, brokerConnectionId);
  } catch (err) {
    throw new Error(`Failed to update webull connection: ${err.message}`);
  }
}

// server/src/services/WebullAPI.ts
var WEBULL_API_BASE = "https://api.webull.com";
var WebullAPI = class {
  /**
   * Build the OAuth authorize URL for Webull.
   */
  static getAuthUrl(appId, redirectUri, state2) {
    const params = new URLSearchParams({
      response_type: "code",
      client_id: appId,
      redirect_uri: redirectUri,
      state: state2,
      scope: "trade.read account.read"
    });
    return `${WEBULL_API_BASE}/oauth2/authorize?${params.toString()}`;
  }
  /**
   * Exchange an OAuth authorization code for access and refresh tokens.
   */
  static async exchangeOAuthCode(opts) {
    const res = await fetch(`${WEBULL_API_BASE}/oauth2/token`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "authorization_code",
        client_id: opts.appId,
        client_secret: opts.appSecret,
        code: opts.code,
        redirect_uri: opts.redirectUri
      }).toString()
    });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Webull OAuth exchange failed (${res.status}): ${text}`);
    }
    const data = await res.json();
    return {
      accessToken: data.access_token,
      refreshToken: data.refresh_token,
      expiresIn: data.expires_in
    };
  }
  /**
   * Refresh an access token using a refresh token.
   */
  static async refreshAccessToken(opts) {
    const res = await fetch(`${WEBULL_API_BASE}/oauth2/token`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "refresh_token",
        client_id: opts.appId,
        client_secret: opts.appSecret,
        refresh_token: opts.refreshToken
      }).toString()
    });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Webull token refresh failed (${res.status}): ${text}`);
    }
    const data = await res.json();
    return {
      accessToken: data.access_token,
      refreshToken: data.refresh_token,
      expiresIn: data.expires_in
    };
  }
  /**
   * Fetch the list of accounts for the authenticated user.
   */
  static async getAccounts(token) {
    const res = await fetch(`${WEBULL_API_BASE}/api/trade/v1/webull/account/list`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Webull getAccounts failed (${res.status}): ${text}`);
    }
    const data = await res.json();
    return (data.accounts || data || []).map((a) => ({
      accountId: String(a.account_id || a.accountId),
      accountType: a.account_type || a.accountType || "unknown",
      currency: a.currency || "USD"
    }));
  }
  /**
   * Fetch filled orders for a specific account.
   * Handles pagination automatically.
   */
  static async getOrders(token, accountId, startDate) {
    const params = new URLSearchParams({ status: "filled", count: "200" });
    if (startDate) params.set("startDate", startDate);
    const allOrders = [];
    let url2 = `${WEBULL_API_BASE}/api/trade/v1/webull/account/${accountId}/orders?${params.toString()}`;
    while (url2) {
      const res = await fetch(url2, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Webull getOrders failed (${res.status}): ${text}`);
      }
      const data = await res.json();
      const orders = data.orders || data || [];
      for (const o of orders) {
        if (!o.filledQty && !o.filled_qty) continue;
        allOrders.push({
          orderId: String(o.order_id || o.orderId),
          ticker: o.ticker?.symbol || o.symbol || o.ticker || "",
          side: (o.side || o.action || "").toUpperCase(),
          orderType: o.order_type || o.orderType || "MARKET",
          status: o.status || "filled",
          filledQty: Number(o.filled_qty || o.filledQty || 0),
          avgFilledPrice: Number(o.avg_filled_price || o.avgFilledPrice || 0),
          filledTime: o.filled_time || o.filledTime || o.updated_at || o.createTime,
          createTime: o.create_time || o.createTime || o.created_at
        });
      }
      url2 = data.next || null;
    }
    return allOrders;
  }
};

