function generateNonce2() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
}
var RENEWAL_THRESHOLD_MS4 = 30 * 60 * 1e3;
async function ensureFreshToken4(env, brokerConnectionId, encryptedToken, encryptedRefreshToken, expiresAt) {
  const token = await decrypt(encryptedToken, env.ENCRYPTION_KEY);
  const expiresAtMs = expiresAt ? new Date(expiresAt).getTime() : 0;
  const now = Date.now();
  if (expiresAtMs - now > RENEWAL_THRESHOLD_MS4) {
    return token;
  }
  if (!encryptedRefreshToken || !env.WEBULL_APP_ID || !env.WEBULL_APP_SECRET) {
    if (expiresAtMs > now) return token;
    throw new Error("Webull oturumunun s\xFCresi doldu. L\xFCtfen hesab\u0131n\u0131z\u0131 yeniden ba\u011Flay\u0131n.");
  }
  try {
    const refreshToken = await decrypt(encryptedRefreshToken, env.ENCRYPTION_KEY);
    const result = await WebullAPI.refreshAccessToken({
      appId: env.WEBULL_APP_ID,
      appSecret: env.WEBULL_APP_SECRET,
      refreshToken
    });
    const newExpiresAt = new Date(Date.now() + result.expiresIn * 1e3).toISOString();
    const serviceClient = getDb();
    await updateByBrokerConnectionId4(serviceClient, brokerConnectionId, {
      access_token: await encrypt(result.accessToken, env.ENCRYPTION_KEY),
      refresh_token: await encrypt(result.refreshToken, env.ENCRYPTION_KEY),
      token_expires_at: newExpiresAt
    });
    return result.accessToken;
  } catch {
    if (expiresAtMs > now) return token;
    throw new Error("Webull oturumunun s\xFCresi doldu ve yenileme ba\u015Far\u0131s\u0131z oldu. L\xFCtfen hesab\u0131n\u0131z\u0131 yeniden ba\u011Flay\u0131n.");
  }
}
