var FEED_URL = "https://nfs.faireconomy.media/ff_calendar_thisweek.json";
var CACHE_TTL_MS = 15 * 60 * 1e3;
var RETRY_AFTER_FAILURE_MS = 5 * 60 * 1e3;
var FETCH_TIMEOUT_MS = 10 * 1e3;
var cache = null;
var lastFailureAt = 0;
var inflight = null;
function normalize(raw2) {
  if (!Array.isArray(raw2)) throw new Error("Unexpected feed format");
  return raw2.filter((e) => e && typeof e === "object" && e.date && e.title).map((e) => ({
    title: String(e.title ?? ""),
    country: String(e.country ?? ""),
    date: String(e.date ?? ""),
    impact: String(e.impact ?? ""),
    forecast: String(e.forecast ?? ""),
    previous: String(e.previous ?? ""),
    actual: String(e.actual ?? "")
  })).filter((e) => !isNaN(new Date(e.date).getTime())).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
}
async function fetchFeed() {
  const controller = new AbortController();
  const timer2 = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(FEED_URL, {
      method: "GET",
      headers: { Accept: "application/json" },
      signal: controller.signal
    });
    if (!res.ok) throw new Error(`Feed responded with HTTP ${res.status}`);
    return normalize(await res.json());
  } finally {
    clearTimeout(timer2);
  }
}
var news = new Hono3();
news.get("/api/news/calendar", requiresLogin, async (c) => {
  const now = Date.now();
  const fresh = cache && now - cache.fetchedAt < CACHE_TTL_MS;
  const inBackoff = now - lastFailureAt < RETRY_AFTER_FAILURE_MS;
  if (fresh || cache && inBackoff) {
    return c.json({
      events: cache.events,
      fetchedAt: new Date(cache.fetchedAt).toISOString(),
      stale: !fresh
    });
  }
  if (!cache && inBackoff) {
    return c.json({ events: [], fetchedAt: null, stale: true, error: "fetch_failed" });
  }
  try {
    if (!inflight) {
      inflight = fetchFeed().finally(() => {
        inflight = null;
      });
    }
    const events = await inflight;
    cache = { events, fetchedAt: Date.now() };
    lastFailureAt = 0;
    return c.json({ events, fetchedAt: new Date(cache.fetchedAt).toISOString(), stale: false });
  } catch (err) {
    lastFailureAt = Date.now();
    console.error("[News] calendar fetch failed:", err?.message || err);
    return c.json({
      events: cache ? cache.events : [],
      fetchedAt: cache ? new Date(cache.fetchedAt).toISOString() : null,
      stale: true,
      error: "fetch_failed"
    });
  }
});
