function upsertNewsItems(db2, items) {
  const exists = db2.prepare("SELECT 1 FROM news_items WHERE id = ?");
  const stmt = db2.prepare(`
    INSERT INTO news_items (id, source_id, source, category, title, summary, url, published_at, first_seen_at, importance, tags, instruments)
    VALUES (@id, @sourceId, @source, @category, @title, @summary, @url, @publishedAt, @firstSeenAt, @importance, @tags, @instruments)
    ON CONFLICT(id) DO UPDATE SET
      title = excluded.title, summary = excluded.summary, importance = excluded.importance,
      tags = excluded.tags, instruments = excluded.instruments, source = excluded.source
  `);
  let inserted = 0;
  db2.transaction(() => {
    for (const it of items) {
      if (!exists.get(it.id)) inserted++;
      stmt.run({ ...it, tags: JSON.stringify(it.tags), instruments: JSON.stringify(it.instruments) });
    }
  })();
  return inserted;
}
function countNewsItemsBySource(db2) {
  const rows = db2.prepare("SELECT source_id, COUNT(*) AS n FROM news_items GROUP BY source_id").all();
  return new Map(rows.map((r3) => [r3.source_id, r3.n]));
}
function listNewsItems(db2, opts) {
  const where = ["importance >= @minImportance"];
  if (opts.category) where.push("category = @category");
  if (opts.since) where.push("first_seen_at > @since");
  return db2.prepare(`SELECT * FROM news_items WHERE ${where.join(" AND ")} ORDER BY published_at DESC LIMIT @limit`).all({ minImportance: opts.minImportance, category: opts.category ?? null, since: opts.since ?? null, limit: opts.limit });
}
function getNewsItem(db2, id) {
  return db2.prepare("SELECT * FROM news_items WHERE id = ?").get(id);
}
function listQueueCandidates(db2, minImportance, limit) {
  return db2.prepare("SELECT * FROM news_items WHERE importance >= ? ORDER BY published_at DESC LIMIT ?").all(minImportance, limit);
}
function pruneNewsItems(db2, olderThanIso) {
  return db2.prepare("DELETE FROM news_items WHERE published_at < ?").run(olderThanIso).changes;
}

