  if (!symbol2 || !Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(entry) || entry <= 0 || !Number.isFinite(exit) || exit <= 0 || !Number.isFinite(multiplier) || multiplier <= 0 || !Number.isFinite(fees) || fees < 0 || !["long", "short"].includes(side)) bad9("Sembol, y\xF6n, pozitif miktar/fiyat/\xE7arpan ve ge\xE7erli masraf girin.");
