// server/src/scheduled/broker-refresh.ts
async function refreshExpiringBrokerTokens(env) {
  const serviceClient = getDb();
  const threshold = new Date(Date.now() + 60 * 60 * 1e3).toISOString();
  try {
    const tvExpiring = await findExpiringSoon(serviceClient, threshold);
    if (tvExpiring.length > 0) {
      console.log(`[Broker Cron] Renewing ${tvExpiring.length} Tradovate token(s)`);
      let renewed = 0, failed = 0;
      for (const row of tvExpiring) {
        try {
          const token = await decrypt(row.access_token, env.ENCRYPTION_KEY);
          const api = new TradovateAPI(row.environment);
          const { accessToken, expiresIn } = await api.renewAccessToken(token);
          const newExpiresAt = new Date(Date.now() + expiresIn * 1e3).toISOString();
          await updateByBrokerConnectionId(serviceClient, row.broker_connection_id, {
            access_token: await encrypt(accessToken, env.ENCRYPTION_KEY),
            token_expires_at: newExpiresAt
          });
          renewed++;
        } catch (err) {
          failed++;
          console.error(`[Broker Cron] Tradovate renewal failed for ${row.broker_connection_id}: ${err.message}`);
        }
      }
      console.log(`[Broker Cron] Tradovate: ${renewed} renewed, ${failed} failed`);
    }
  } catch (err) {
    console.error(`[Broker Cron] Tradovate query error: ${err.message}`);
  }
  try {
    const pxExpiring = await findExpiringSoon2(serviceClient, threshold);
    if (pxExpiring.length > 0) {
      console.log(`[Broker Cron] Re-authenticating ${pxExpiring.length} ProjectX token(s)`);
      let renewed = 0, failed = 0;
      for (const row of pxExpiring) {
        try {
          if (!row.username || !row.api_key) {
            failed++;
            continue;
          }
          const apiKey = await decrypt(row.api_key, env.ENCRYPTION_KEY);
          const api = new ProjectXAPI();
          const newToken = await api.authenticate(row.username, apiKey);
          const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1e3).toISOString();
          await updateByBrokerConnectionId2(serviceClient, row.broker_connection_id, {
            access_token: await encrypt(newToken, env.ENCRYPTION_KEY),
            token_expires_at: expiresAt
          });
          renewed++;
        } catch (err) {
          failed++;
          console.error(`[Broker Cron] ProjectX re-auth failed for ${row.broker_connection_id}: ${err.message}`);
        }
      }
      console.log(`[Broker Cron] ProjectX: ${renewed} renewed, ${failed} failed`);
    }
  } catch (err) {
    console.error(`[Broker Cron] ProjectX query error: ${err.message}`);
  }
  try {
    const cutoff = new Date(Date.now() - 60 * 60 * 1e3).toISOString();
    const cleaned = await cleanupPending(serviceClient, cutoff);
    if (cleaned > 0) {
      console.log(`[Broker Cron] Cleaned up ${cleaned} pending OAuth connection(s)`);
    }
  } catch (err) {
    console.error(`[Broker Cron] Pending cleanup error: ${err.message}`);
  }
}

// server/src/services/reminders/index.ts
var TICK_MS2 = 60 * 1e3;
var LATE_GRACE_MS = 2 * 60 * 1e3;
var DIGEST_WINDOW_MIN = 120;
var MAX_REMINDERS_PER_TICK = 10;
var timer = null;
var running2 = false;
var lastPrune = 0;
function dueAt(row) {
  const [y, m, d] = row.due_date.split("-").map(Number);
  const [hh, mm] = row.due_time.split(":").map(Number);
  return new Date(y, m - 1, d, hh, mm, 0, 0).getTime();
}
async function taskReminders(userId, s, now) {
  if (!s.taskReminders || inQuietHours(s.quietHours, now)) return 0;
  const today = localYmd(now);
  const rows = remindersDb().prepare(
    `SELECT id, title, due_date, due_time, priority FROM tasks
       WHERE user_id = ? AND status = 'open' AND due_time IS NOT NULL AND due_date IN (?, ?, ?)
       ORDER BY due_date, due_time`
  ).all(userId, addDays(today, -1), today, addDays(today, 1));
  const lead = s.reminderLeadMinutes * 60 * 1e3;
  const t = now.getTime();
  let sent = 0;
  for (const r3 of rows) {
    if (sent >= MAX_REMINDERS_PER_TICK) break;
    const at = dueAt(r3);
    if (!Number.isFinite(at) || at - t > lead || at < t - LATE_GRACE_MS) continue;
    const key2 = `${r3.due_date} ${r3.due_time}`;
    if (!claimOnce(userId, r3.id, key2)) continue;
    const mins = Math.max(0, Math.round((at - t) / 6e4));
    const res = await sendNtfy(s, {
      title: mins > 0 ? `G\xF6rev ${mins} dk sonra` : "G\xF6rev zaman\u0131 geldi",
      body: `${r3.title.slice(0, 300)} (${r3.due_time})`,
      priority: r3.priority === 1 ? 5 : 4,
      tags: ["alarm_clock"]
    });
    if (res.ok) sent++;
    else {
      releaseClaim(userId, r3.id, key2);
      console.warn("[Reminders] task push failed:", res.error);
    }
  }
  return sent;
}
async function upcomingHighImpact(now) {
  try {
    const res = await news_default.request("/api/news/calendar");
    if (!res.ok) return null;
    const data = await res.json();
    if (!Array.isArray(data.events) || data.error && !data.events.length) return null;
    const today = localYmd(now);
    return data.events.filter((e) => e && e.impact === "High").filter((e) => {
      const d = new Date(e.date);
      return !Number.isNaN(d.getTime()) && d.getTime() >= now.getTime() && localYmd(d) === today;
    }).slice(0, 5);
  } catch {
    return null;
  }
}
async function buildDigest(userId, now) {
  const today = localYmd(now);
  const db2 = remindersDb();
  const count = (sql) => db2.prepare(sql).get(userId, today).n;
  const dueToday = count("SELECT COUNT(*) AS n FROM tasks WHERE user_id = ? AND status = 'open' AND due_date = ?");
  const overdue = count("SELECT COUNT(*) AS n FROM tasks WHERE user_id = ? AND status = 'open' AND due_date < ?");
  const top = db2.prepare(
    `SELECT title, due_time FROM tasks WHERE user_id = ? AND status = 'open' AND due_date = ?
       ORDER BY due_time IS NULL, due_time, priority LIMIT 3`
  ).all(userId, today);
  const lines = [`Bug\xFCn ${dueToday} g\xF6rev, gecikmi\u015F ${overdue} g\xF6rev.`];
  for (const t of top) lines.push(`\u2022 ${t.due_time ? t.due_time + " " : ""}${t.title.slice(0, 120)}`);
  const events = await upcomingHighImpact(now);
  if (events && events.length) {
    lines.push("", "Y\xFCksek etkili takvim:");
    for (const e of events) {
      const hm = new Date(e.date).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" });
      lines.push(`\u2022 ${hm} ${e.country} ${e.title}`.slice(0, 140));
    }
  } else if (events) {
    lines.push("", "Bug\xFCn kalan y\xFCksek etkili takvim olay\u0131 yok.");
  }
  return { title: "G\xFCnayd\u0131n \xB7 G\xFCnl\xFCk \xF6zet", body: lines.join("\n") };
}
async function morningDigest(userId, s, now) {
  if (!s.morningDigest) return false;
  const diff = minutesOf(localHm(now)) - minutesOf(s.digestTime);
  if (diff < 0 || diff > DIGEST_WINDOW_MIN) return false;
  const day = localYmd(now);
  if (!claimOnce(userId, "digest", day)) return false;
  const d = await buildDigest(userId, now);
  const res = await sendNtfy(s, { ...d, priority: 3, tags: ["sunrise"] });
  if (!res.ok) {
    releaseClaim(userId, "digest", day);
    console.warn("[Reminders] digest push failed:", res.error);
  }
  return res.ok;
}
async function runReminderTick(now = /* @__PURE__ */ new Date()) {
  const out = { reminders: 0, digests: 0 };
  if (running2) return out;
  running2 = true;
  try {
    if (Date.now() - lastPrune > 24 * 60 * 60 * 1e3) {
      lastPrune = Date.now();
      try {
        pruneSent();
      } catch {
      }
    }
    for (const { userId, settings } of enabledNtfyUsers()) {
      try {
        out.reminders += await taskReminders(userId, settings, now);
        if (await morningDigest(userId, settings, now)) out.digests++;
      } catch (err) {
        console.warn("[Reminders] tick failed for user:", err?.message || err);
      }
    }
  } catch (err) {
    console.warn("[Reminders] tick failed:", err?.message || err);
  } finally {
    running2 = false;
  }
  return out;
}
function startReminders() {
  if (timer) return;
  timer = setInterval(() => {
    runReminderTick().catch(() => {
    });
  }, TICK_MS2);
  timer.unref();
}

