function startGoogleSync() {
  if (started3) return;
  started3 = true;
  try {
    const first = setTimeout(() => {
      void runAutoSync();
    }, FIRST_RUN_DELAY_MS);
    first.unref?.();
    const timer2 = setInterval(() => {
      void runAutoSync();
    }, SYNC_INTERVAL_MS);
    timer2.unref?.();
  } catch (err) {
    console.error("[Google sync] could not start:", err);
  }
}

